mapper.select:
SELECT EXISTS(SELECT 1 FROM pf.file_operation o JOIN pf.workspace_file_lease l
  ON l.space_id=o.space_id AND l.workspace_id=o.workspace_id AND l.operation_id=o.id
  AND l.owner_id=o.owner_id AND l.fence=o.fence
  WHERE o.id=#{command.operation.id} AND o.space_id=#{command.operation.spaceId}
  AND o.workspace_id=#{command.operation.workspaceId} AND o.owner_id=#{command.operation.ownerId}
  AND o.command_id=#{command.operation.commandId} AND o.generation=#{command.operation.generation}
  AND o.fence=#{command.operation.fence} AND o.status='UNKNOWN' AND l.status='BLOCKED'
  AND o.lease_until<=clock_timestamp() AND o.deadline_at<=clock_timestamp()
  AND l.lease_until<=clock_timestamp())
